import type { Card } from "@/lib/topics";

export const expandedQuestions: Record<string, Card[]> = {
  "java-8-21": [
    { id: "java-8-21-extra-01", question: "What is the difference between a primitive and a reference type in Java?", answer: "A primitive stores a value directly, while a reference stores a link to an object. Primitives cannot be null, but references can." },
    { id: "java-8-21-extra-02", question: "Why are String objects immutable in Java?", answer: "Immutability makes strings safe to share, suitable as map keys, and safe for caching and class loading. Operations that appear to change a String create a new object." },
    { id: "java-8-21-extra-03", question: "What is the difference between an ArrayList and a LinkedList?", answer: "ArrayList gives fast indexed access and usually better cache locality, while LinkedList has costly indexed access. Prefer ArrayList unless frequent linked-node insertion is proven necessary." },
    { id: "java-8-21-extra-04", question: "How does a HashMap find a value?", answer: "It hashes the key to select a bucket, then compares keys using hashCode and equals. Correct immutable key equality and hashing are essential." },
    { id: "java-8-21-extra-05", question: "What is the contract between equals and hashCode?", answer: "Objects that are equal must have the same hash code. Unequal objects may collide, but changing fields used by either method while an object is a map key breaks lookup." },
    { id: "java-8-21-extra-06", question: "When should you use Optional in Java?", answer: "Use Optional mainly for return values that may be absent and make callers handle that case. Avoid it for fields, parameters, and collections, where it often adds noise." },
    { id: "java-8-21-extra-07", question: "What does a lambda expression represent?", answer: "A lambda is an implementation of a functional interface, an interface with one abstract method. It lets behavior be passed as a value." },
    { id: "java-8-21-extra-08", question: "What is a functional interface?", answer: "It has exactly one abstract method and can be implemented with a lambda. It may also contain default and static methods." },
    { id: "java-8-21-extra-09", question: "When would you use a Stream instead of a loop?", answer: "Use a Stream for a readable pipeline of transformations, filtering, and aggregation. Use a loop when control flow, mutation, or debugging would be clearer imperatively." },
    { id: "java-8-21-extra-10", question: "Why should stream operations avoid side effects?", answer: "Side effects make ordering, parallel execution, and reasoning harder. Prefer transformations that return values and collect results explicitly." },
    { id: "java-8-21-extra-11", question: "What is the difference between map and flatMap on a Stream?", answer: "map transforms each element into one result, while flatMap transforms each element into a stream and flattens the results into one stream." },
    { id: "java-8-21-extra-12", question: "What does lazy evaluation mean for Java Streams?", answer: "Intermediate operations do not run until a terminal operation is invoked. This permits operation fusion and short-circuiting such as findFirst." },
    { id: "java-8-21-extra-13", question: "What is a record in modern Java?", answer: "A record is a concise declaration for an immutable data carrier with generated accessors, equals, hashCode, and toString. It is useful for value-like data, not behavior-heavy entities." },
    { id: "java-8-21-extra-14", question: "When would you use a sealed class?", answer: "Use a sealed class or interface when the permitted subtype set is intentionally closed. The compiler can then check exhaustive handling of that hierarchy." },
    { id: "java-8-21-extra-15", question: "What problem does pattern matching for instanceof solve?", answer: "It combines the type check and cast, reducing duplicate syntax and narrowing the variable safely. It improves readability without changing the underlying type rules." },
    { id: "java-8-21-extra-16", question: "What is the purpose of var in Java?", answer: "var infers a local variable's static type from its initializer. It does not make Java dynamically typed, and it should be used only when the inferred type remains clear." },
    { id: "java-8-21-extra-17", question: "How do default interface methods affect API evolution?", answer: "They let an interface add behavior without immediately breaking all implementors. Defaults still need a coherent contract and can create conflicts when interfaces are combined." },
    { id: "java-8-21-extra-18", question: "What is a method reference?", answer: "A method reference is compact syntax for a lambda that delegates to an existing method, such as String::trim. It is useful when the target method already expresses the needed behavior." },
    { id: "java-8-21-extra-19", question: "What is the difference between checked and unchecked exceptions in API design?", answer: "Checked exceptions force callers to acknowledge recoverable conditions, while unchecked exceptions avoid mandatory handling. Choose based on whether callers can reasonably recover, not on convenience alone." },
    { id: "java-8-21-extra-20", question: "What does try-with-resources guarantee?", answer: "It closes each AutoCloseable resource when the block exits, including exceptional exits. Close failures are preserved as suppressed exceptions when another exception is primary." },
    { id: "java-8-21-extra-21", question: "How does garbage collection affect Java application design?", answer: "The collector reclaims unreachable objects, but allocation rate and retained references still affect latency and memory. Avoid leaks through unbounded caches, listeners, and collections." },
    { id: "java-8-21-extra-22", question: "What is a memory leak in a garbage-collected language?", answer: "It is unintended retention of objects that are still reachable but no longer useful. Common causes include static collections, forgotten listeners, and caches without bounds." },
    { id: "java-8-21-extra-23", question: "What is the difference between heap and stack memory?", answer: "Objects generally live on the heap and are managed by garbage collection, while each thread has a stack for call frames and local references. Stack exhaustion commonly comes from deep recursion." },
    { id: "java-8-21-extra-24", question: "What is the Java Memory Model concerned with?", answer: "It defines how threads see shared memory, including visibility, ordering, and atomicity. Synchronization, volatile, and safe publication establish the needed happens-before relationships." },
    { id: "java-8-21-extra-25", question: "When is volatile appropriate?", answer: "volatile is appropriate for visibility of a simple independent state such as a shutdown flag. It does not make compound actions like increment atomic." },
    { id: "java-8-21-extra-26", question: "What is the difference between synchronized and Lock?", answer: "synchronized provides simple monitor-based mutual exclusion with automatic release, while Lock offers features such as timed acquisition and interruptible locking. Prefer synchronized unless those features are needed." },
    { id: "java-8-21-extra-27", question: "How does ConcurrentHashMap differ from HashMap?", answer: "ConcurrentHashMap supports safe concurrent access with specialized coordination, while HashMap requires external synchronization for shared mutation. ConcurrentHashMap also disallows null keys and values." },
    { id: "java-8-21-extra-28", question: "What problem does CompletableFuture solve?", answer: "It represents an asynchronous result and composes dependent stages without deeply nested callbacks. Its executor, exception paths, and blocking calls still require deliberate control." },
    { id: "java-8-21-extra-29", question: "Why can parallel streams be harmful?", answer: "They use shared pool resources and add coordination overhead, so small tasks or blocking I/O may become slower or interfere with unrelated work. Measure before using them." },
    { id: "java-8-21-extra-30", question: "What is a virtual thread in Java?", answer: "A virtual thread is a lightweight thread managed by the JVM that can make blocking I/O scale with less platform-thread cost. It does not make CPU work faster or remove external limits." },
    { id: "java-8-21-extra-31", question: "When should a service use virtual threads?", answer: "Use them for many concurrent, mostly blocking tasks when libraries cooperate with unmounting. Bound database and downstream concurrency because virtual threads do not create unlimited capacity." },
    { id: "java-8-21-extra-32", question: "What is a structured concurrency goal?", answer: "It treats related concurrent tasks as one scope with clear lifetime, cancellation, and failure handling. This prevents child work from escaping its request unnoticed." },
    { id: "java-8-21-extra-33", question: "What is a class loader responsible for?", answer: "A class loader locates and defines classes and separates namespaces. Two classes with the same name loaded by different loaders can still be different types." },
    { id: "java-8-21-extra-34", question: "How would you diagnose a Java memory spike?", answer: "Check heap, allocation, GC pause, and old-generation metrics, then capture a heap dump if safe. Identify retained objects and correlate the change with deployment or traffic." },
    { id: "java-8-21-extra-35", question: "How would you diagnose high Java CPU usage?", answer: "Compare process and thread CPU, capture thread dumps or a profiler sample, and identify hot methods or contention. Validate the fix under representative load." },
    { id: "java-8-21-extra-36", question: "What makes an object safely immutable?", answer: "Make its state final where possible, validate construction, expose no mutable internals, and defensively copy mutable inputs and outputs. Immutability simplifies sharing between threads." },
    { id: "java-8-21-extra-37", question: "What is serialization versioning risk?", answer: "Binary or serialized data may outlive the class shape, so incompatible changes can prevent deserialization or corrupt meaning. Prefer explicit formats and compatibility tests for durable data." },
    { id: "java-8-21-extra-38", question: "How do you choose a Java collection for a new feature?", answer: "Start with access patterns, ordering, uniqueness, mutation, concurrency, and expected size. Choose the simplest collection whose documented behavior matches those requirements." },
    { id: "java-8-21-extra-39", question: "How do you upgrade a Java 8 service toward Java 21?", answer: "Inventory runtime and library compatibility, upgrade in stages, run tests and production-like performance checks, then adopt newer features where they reduce risk or complexity." },
    { id: "java-8-21-extra-40", question: "How would you investigate a latency regression after a JDK upgrade?", answer: "Compare workload, GC, CPU, allocation, locks, and dependency versions against a controlled baseline. Use profiling and rollback criteria rather than attributing the change to the JDK alone." },
  ],
  oop: [
    { id: "oop-extra-01", question: "What is the purpose of an object in object-oriented design?", answer: "An object groups state with the operations and rules that govern that state. Good objects protect invariants rather than merely exposing data." },
    { id: "oop-extra-02", question: "What is abstraction in OOP?", answer: "Abstraction exposes the concepts and operations a client needs while hiding irrelevant implementation detail. A small interface is one common mechanism for it." },
    { id: "oop-extra-03", question: "What is inheritance?", answer: "Inheritance creates a subtype relationship in which a child reuses or specializes a parent contract. It should model substitutable behavior, not just shared code." },
    { id: "oop-extra-04", question: "What is composition?", answer: "Composition builds an object from collaborators that provide focused behavior. It usually allows behavior to vary without coupling the whole type hierarchy." },
    { id: "oop-extra-05", question: "What does the single responsibility principle mean in practice?", answer: "A class should have one coherent reason to change. It may contain several methods when those methods serve the same responsibility and stakeholder." },
    { id: "oop-extra-06", question: "What does the open-closed principle protect?", answer: "It encourages adding new behavior through extension points rather than repeatedly editing stable decision logic. The extension must still preserve the original contract." },
    { id: "oop-extra-07", question: "What does interface segregation mean?", answer: "Clients should depend on focused interfaces containing only operations they need. Smaller contracts reduce accidental coupling and make test doubles simpler." },
    { id: "oop-extra-08", question: "What does dependency inversion mean?", answer: "High-level policy should depend on abstractions, while infrastructure implements those abstractions. This keeps business rules independent from databases and frameworks." },
    { id: "oop-extra-09", question: "What is a value object?", answer: "A value object is defined by its values rather than identity, such as Money or EmailAddress. It is commonly immutable and validates its invariant at construction." },
    { id: "oop-extra-10", question: "What is an entity?", answer: "An entity has continuity and identity even when its attributes change. Its identity should be distinct from a value object's equality." },
    { id: "oop-extra-11", question: "What is an anemic domain model?", answer: "It is a model whose classes mainly expose data while services hold nearly all behavior. It can be acceptable for simple CRUD, but it weakens encapsulation for rich rules." },
    { id: "oop-extra-12", question: "When is a data transfer object useful?", answer: "A DTO defines the data shape crossing a boundary such as HTTP or messaging. It prevents external formats from dictating internal domain objects." },
    { id: "oop-extra-13", question: "What is a tell-dont-ask design rule?", answer: "Tell an object to perform an operation instead of extracting its state and making the decision elsewhere. This keeps the rule near the data it protects." },
    { id: "oop-extra-14", question: "Why can getters and setters be harmful?", answer: "They can expose representation and let any caller create invalid states. Expose intent-based operations when the object owns meaningful invariants." },
    { id: "oop-extra-15", question: "What is a cohesion problem?", answer: "A class has low cohesion when its members serve unrelated responsibilities. Such a class is harder to name, test, and change safely." },
    { id: "oop-extra-16", question: "What is coupling in object design?", answer: "Coupling is the degree to which one component depends on another component's details. Narrow contracts and dependency injection reduce unnecessary coupling." },
    { id: "oop-extra-17", question: "How do you identify a useful interface?", answer: "Start with a client need and name the behavior it requires, not the implementation behind it. The interface should have a stable, coherent contract." },
    { id: "oop-extra-18", question: "When is a strategy pattern appropriate?", answer: "Use Strategy when one policy has multiple interchangeable algorithms selected by context. It is unnecessary when there is only one stable algorithm." },
    { id: "oop-extra-19", question: "When is a factory useful?", answer: "A factory is useful when creation involves validation, selecting a subtype, or assembling dependencies. It keeps construction policy out of callers." },
    { id: "oop-extra-20", question: "When is a builder useful?", answer: "A builder helps construct an object with many optional values while keeping validation centralized. For a few required fields, a constructor or factory is clearer." },
    { id: "oop-extra-21", question: "What is the decorator pattern?", answer: "Decorator wraps an object with the same contract and adds behavior such as logging or caching. It avoids modifying the wrapped implementation or creating many subclasses." },
    { id: "oop-extra-22", question: "What is the adapter pattern?", answer: "An adapter translates one interface into another expected by a client. It isolates incompatible vendor or legacy APIs at the boundary." },
    { id: "oop-extra-23", question: "What is a domain service?", answer: "A domain service holds a domain operation that does not naturally belong to one entity or value object. It should express domain policy rather than transport or persistence work." },
    { id: "oop-extra-24", question: "What is an aggregate in domain modeling?", answer: "An aggregate is a consistency boundary with one root through which changes are made. Rules that must be atomic should be enforced inside that boundary." },
    { id: "oop-extra-25", question: "Why should aggregate boundaries stay small?", answer: "Small boundaries reduce contention, transaction size, and accidental coupling. They keep each consistency decision explicit." },
    { id: "oop-extra-26", question: "What is the command-query separation principle?", answer: "A command changes state and a query returns information without changing state. Separating them makes behavior and side effects easier to reason about." },
    { id: "oop-extra-27", question: "How do you avoid a god object?", answer: "Give each responsibility an owner, extract cohesive collaborators, and keep orchestration separate from policy. Use tests to preserve behavior during each extraction." },
    { id: "oop-extra-28", question: "How do you design a class for testability?", answer: "Keep decisions deterministic, inject external effects, expose a focused contract, and avoid hidden global state. Tests should not need the network or clock unless that is the subject." },
    { id: "oop-extra-29", question: "What is substitutability in practical terms?", answer: "A replacement must honor the promises clients rely on, including errors, timing assumptions, and side effects. Matching method signatures alone is insufficient." },
    { id: "oop-extra-30", question: "Why are deep inheritance hierarchies risky?", answer: "Behavior is spread across ancestors and overrides, so small changes create surprising effects. Prefer shallow hierarchies and composition for independent variation." },
    { id: "oop-extra-31", question: "How can a subtype violate a parent contract?", answer: "It can reject valid parent inputs, weaken guarantees, strengthen unexpected preconditions, or change side effects. Such a type should use a different abstraction." },
    { id: "oop-extra-32", question: "What is the difference between delegation and inheritance?", answer: "Delegation forwards work to a collaborator, while inheritance reuses and specializes a parent implementation. Delegation keeps the relationship explicit and usually more replaceable." },
    { id: "oop-extra-33", question: "How do you model a finite workflow with objects?", answer: "Represent valid states and transitions explicitly, often with a state or sealed hierarchy. Reject transitions that are not legal instead of relying on scattered conditionals." },
    { id: "oop-extra-34", question: "How do you prevent temporal coupling between methods?", answer: "Make required order explicit through construction, a cohesive operation, or state-specific types. Avoid APIs where callers must remember an undocumented sequence." },
    { id: "oop-extra-35", question: "What is the danger of exposing a mutable collection?", answer: "Callers can bypass validation and change internal state unexpectedly. Return an immutable view or defensive copy and provide intent-based mutation methods." },
    { id: "oop-extra-36", question: "How do you choose between inheritance and an interface?", answer: "Use an interface for a capability or boundary and inheritance only for a genuine substitutable hierarchy with shared lifecycle or state. Do not inherit solely to reuse code." },
    { id: "oop-extra-37", question: "How do you refactor a conditional type switch?", answer: "Identify whether each branch is a stable subtype, policy, or data mapping. Replace it with polymorphism only when the variation is real and the new contract is clearer." },
    { id: "oop-extra-38", question: "How do you review an object API for accidental coupling?", answer: "Check exposed fields, concrete dependencies, mutable returns, lifecycle order, and leaked infrastructure types. Ask whether a caller can change when the implementation changes." },
    { id: "oop-extra-39", question: "How do you evolve a public object contract safely?", answer: "Add compatible behavior, preserve old guarantees, deprecate deliberately, and test representative clients. Breaking changes need migration guidance and a versioning strategy." },
    { id: "oop-extra-40", question: "How do you decide whether a design pattern belongs in production code?", answer: "Use a pattern when it names and reduces a recurring design problem. Do not add one merely to demonstrate vocabulary or create indirection without a changing requirement." },
  ],
  "software-design": [
    { id: "software-design-extra-01", question: "What makes a software requirement testable?", answer: "It states observable behavior, inputs, outputs, constraints, and failure conditions without relying on vague words such as fast or easy." },
    { id: "software-design-extra-02", question: "What is the difference between functional and nonfunctional requirements?", answer: "Functional requirements describe what the system does, while nonfunctional requirements describe qualities such as latency, security, availability, and maintainability." },
    { id: "software-design-extra-03", question: "What is separation of concerns?", answer: "It keeps different reasons for change in distinct parts of the system. For example, HTTP parsing should not decide domain pricing policy." },
    { id: "software-design-extra-04", question: "What is a module boundary?", answer: "A module boundary defines ownership, allowed dependencies, and the contract through which code interacts. A useful boundary lets internals change independently." },
    { id: "software-design-extra-05", question: "What is an API contract?", answer: "It specifies requests, responses, errors, compatibility rules, and relevant operational behavior. A method signature alone is not a complete contract." },
    { id: "software-design-extra-06", question: "Why should APIs be designed around use cases?", answer: "Use-case-oriented APIs expose meaningful operations and validation instead of leaking internal tables or object graphs. This reduces client coupling." },
    { id: "software-design-extra-07", question: "What is idempotency?", answer: "An operation is idempotent when repeating the same request has the same intended effect as doing it once. It is essential for safe retries of many write operations." },
    { id: "software-design-extra-08", question: "Why are timeouts part of a service design?", answer: "Without timeouts, blocked dependencies consume threads and capacity until the service fails. Every remote call needs a bounded deadline and a defined failure path." },
    { id: "software-design-extra-09", question: "What is a circuit breaker for?", answer: "A circuit breaker stops repeatedly calling an unhealthy dependency, allowing recovery and protecting local capacity. It should expose a deliberate fallback or error." },
    { id: "software-design-extra-10", question: "What is a bulkhead in service design?", answer: "A bulkhead isolates resources such as threads or connection pools for different dependencies. One failing workload then cannot consume all shared capacity." },
    { id: "software-design-extra-11", question: "What is backpressure?", answer: "Backpressure limits producers when consumers cannot keep up. It prevents unbounded queues and forces the system to reject, delay, or shed work explicitly." },
    { id: "software-design-extra-12", question: "What is an anti-corruption layer?", answer: "It translates an external or legacy model into the application's model and prevents foreign concepts from spreading through the domain." },
    { id: "software-design-extra-13", question: "What is hexagonal architecture?", answer: "It places application and domain logic at the center and connects external systems through ports and adapters. This isolates policy from infrastructure details." },
    { id: "software-design-extra-14", question: "What is a layered architecture?", answer: "It organizes code into layers with directional dependencies, such as presentation, application, domain, and infrastructure. The rules must be explicit enough to prevent layer bypasses." },
    { id: "software-design-extra-15", question: "When is a modular monolith preferable to microservices?", answer: "Use it when one deployable unit is simpler for the team and scale or ownership boundaries are not yet proven. Enforced modules preserve a path to later extraction." },
    { id: "software-design-extra-16", question: "What cost does a microservice add?", answer: "It adds network failure, deployment, observability, data ownership, and operational overhead. The service should earn that cost through independent scaling, ownership, or release needs." },
    { id: "software-design-extra-17", question: "What is eventual consistency?", answer: "Replicas or services may temporarily show different values but converge after successful propagation. The product must define what stale data users can tolerate." },
    { id: "software-design-extra-18", question: "What is the transactional outbox pattern?", answer: "The service writes its business change and an event record in one local transaction, then publishes the event asynchronously. This avoids losing events between a database commit and a broker call." },
    { id: "software-design-extra-19", question: "What is a saga?", answer: "A saga coordinates a distributed business process through local transactions and compensating actions. It accepts that a global transaction is unavailable or undesirable." },
    { id: "software-design-extra-20", question: "What is a distributed transaction tradeoff?", answer: "It can provide stronger cross-system atomicity but increases latency, coupling, and failure complexity. Prefer local transactions with explicit workflows when the business allows it." },
    { id: "software-design-extra-21", question: "How do you choose between synchronous and asynchronous communication?", answer: "Choose synchronous communication when the caller needs an immediate result; choose asynchronous messaging when work can be delayed and needs buffering or independent retry." },
    { id: "software-design-extra-22", question: "What is a versioned API migration strategy?", answer: "Add the new contract, support both during migration, observe usage, and remove the old version only after clients have moved. Keep translation at the boundary." },
    { id: "software-design-extra-23", question: "What is a feature flag useful for?", answer: "It separates deployment from release and enables controlled rollout or rollback. Flags need owners, expiry dates, and tests for both states." },
    { id: "software-design-extra-24", question: "What is observability in a distributed system?", answer: "It is the ability to infer internal behavior from logs, metrics, and traces. Correlation IDs and useful dimensions make a request followable across boundaries." },
    { id: "software-design-extra-25", question: "What is a service level objective?", answer: "An SLO is a target for a measurable reliability or performance indicator over a period. It guides engineering tradeoffs more effectively than an absolute promise." },
    { id: "software-design-extra-26", question: "What is an error budget?", answer: "An error budget is the allowable unreliability implied by an SLO. Teams can spend it on change, but repeated exhaustion should slow risky releases and prioritize reliability." },
    { id: "software-design-extra-27", question: "How do you design graceful degradation?", answer: "Identify which features are essential, define stale or reduced alternatives for optional features, and communicate limitations clearly. Never silently return data that looks authoritative when it is not." },
    { id: "software-design-extra-28", question: "How do you prevent a retry storm?", answer: "Use bounded exponential backoff with jitter, retry only transient failures, cap concurrency, and centralize retry ownership. Record attempts and honor deadlines." },
    { id: "software-design-extra-29", question: "How do you decide where to cache?", answer: "Cache stable, expensive data where staleness is acceptable, define invalidation and size limits, and measure hit rate. Do not cache sensitive data without an explicit security design." },
    { id: "software-design-extra-30", question: "What is a good database ownership rule for services?", answer: "The service that owns a business capability should own its schema and invariants. Other services should use an API or event rather than querying its tables directly." },
    { id: "software-design-extra-31", question: "What is a strangler migration?", answer: "It gradually routes parts of a legacy capability to a replacement while the old system remains available. Each slice is verified before more behavior moves." },
    { id: "software-design-extra-32", question: "How do you design for recoverability?", answer: "Define backups, restore tests, replay or reconciliation procedures, dependency recovery, and clear operators. Recovery time and data loss targets must be measurable." },
    { id: "software-design-extra-33", question: "What is a threat model?", answer: "It systematically identifies assets, trust boundaries, threats, mitigations, and residual risk. It should influence design before implementation, not only audit afterward." },
    { id: "software-design-extra-34", question: "How do you minimize secrets exposure in a design?", answer: "Use a managed secret store, short-lived identities, least privilege, redaction, rotation, and separate environments. Avoid placing secrets in source, logs, URLs, or client bundles." },
    { id: "software-design-extra-35", question: "How should a design handle partial failure?", answer: "Set deadlines, isolate dependencies, make operations retry-safe, record uncertain outcomes, and provide reconciliation. Assume any remote call can succeed remotely while its response is lost." },
    { id: "software-design-extra-36", question: "How do you compare two architecture options?", answer: "Compare them against explicit requirements, failure modes, scale, team capability, cost, delivery time, and reversibility. Record assumptions and the evidence that would change the decision." },
    { id: "software-design-extra-37", question: "What belongs in an architecture decision record?", answer: "Capture context, decision, alternatives, consequences, constraints, and review triggers. Keep it concise and link it to the affected component." },
    { id: "software-design-extra-38", question: "How do you keep architecture from drifting?", answer: "Make boundaries executable with tests or checks, review dependency changes, document ownership, and periodically compare production behavior with the intended design." },
    { id: "software-design-extra-39", question: "How do you design a safe deletion of an old feature?", answer: "Measure usage, announce deprecation, disable new writes if needed, migrate or archive data, remove dependencies, and keep a rollback or recovery path until evidence supports deletion." },
    { id: "software-design-extra-40", question: "What is the most important question in a design review?", answer: "Ask which requirement or failure mode the design is optimizing for and what it gives up. This exposes hidden assumptions and makes tradeoffs reviewable." },
  ],
  spring: [
    { id: "spring-extra-01", question: "What is Spring Framework used for?", answer: "Spring provides infrastructure for dependency injection, web applications, data access, configuration, and cross-cutting concerns. It lets application code depend less directly on platform details." },
    { id: "spring-extra-02", question: "What is dependency injection?", answer: "Dependency injection gives a class its collaborators from outside instead of having it construct them. This makes ownership, configuration, and testing clearer." },
    { id: "spring-extra-03", question: "Why is constructor injection preferred in Spring?", answer: "It makes required dependencies explicit, supports immutable fields, and prevents partially constructed objects. It also makes unit tests simple to assemble." },
    { id: "spring-extra-04", question: "What does a Spring bean represent?", answer: "A bean is an object created, configured, and managed by the Spring container. Its lifecycle and scope are controlled by configuration and annotations." },
    { id: "spring-extra-05", question: "What is the default scope of a Spring bean?", answer: "The default scope is singleton per application context. That means the bean must be safe for concurrent requests and should not hold request-specific mutable state." },
    { id: "spring-extra-06", question: "When would you use prototype scope?", answer: "Use prototype when the container should create a new instance on each request for that bean. It does not make lifecycle management of the created object automatic after injection." },
    { id: "spring-extra-07", question: "What does @Configuration do?", answer: "It marks a class as a source of bean definitions that Spring can process. Methods annotated with @Bean describe objects managed by the container." },
    { id: "spring-extra-08", question: "What is component scanning?", answer: "Component scanning finds classes marked with stereotypes such as @Component and registers them as beans. Restrict scan boundaries to avoid accidental or ambiguous registrations." },
    { id: "spring-extra-09", question: "How do Spring profiles help configuration?", answer: "Profiles select environment-specific beans or properties, such as local versus production integrations. They should not be used to hide fundamentally different business behavior." },
    { id: "spring-extra-10", question: "How should Spring configuration properties be modeled?", answer: "Bind related settings into typed configuration objects, validate required values, and keep secrets in a secret manager. Avoid scattering string lookups throughout business code." },
    { id: "spring-extra-11", question: "What is the role of a Spring controller?", answer: "A controller translates transport requests into application calls and maps results or errors back to transport responses. It should not contain core business policy." },
    { id: "spring-extra-12", question: "Where should validation occur in a Spring application?", answer: "Validate shape and basic constraints at the request boundary, then enforce business invariants in the application or domain layer. Both layers should return consistent errors." },
    { id: "spring-extra-13", question: "What does @RestController imply?", answer: "It combines controller behavior with response-body serialization for handler results. It is appropriate for HTTP APIs whose responses are data rather than view names." },
    { id: "spring-extra-14", question: "How should a Spring API represent errors?", answer: "Use a consistent status, machine-readable code, message safe for clients, and correlation reference. Central exception handling avoids duplicating error mapping in every controller." },
    { id: "spring-extra-15", question: "What does @Transactional provide?", answer: "It defines transaction behavior around a method or class, including commit and rollback rules. The boundary should match a business unit of work and avoid unnecessary remote calls." },
    { id: "spring-extra-16", question: "Why can self-invocation bypass Spring transactions?", answer: "Spring commonly applies transactions through a proxy, and a call from one method to another on the same object can bypass that proxy. Move the boundary to another bean or use a deliberate proxy-aware design." },
    { id: "spring-extra-17", question: "What is transaction propagation?", answer: "Propagation defines how a method joins or creates a transaction when one already exists. Choose it based on business atomicity rather than using REQUIRES_NEW as a generic fix." },
    { id: "spring-extra-18", question: "How do isolation levels affect Spring transactions?", answer: "Isolation controls which concurrent changes a transaction can observe and can trade consistency for throughput. Choose the lowest level that preserves the business invariant and verify database behavior." },
    { id: "spring-extra-19", question: "What is the N+1 query problem in Spring Data?", answer: "The application loads a collection and then issues one query per item, causing query count to grow with data size. Use a suitable fetch plan, projection, or explicit query and measure it." },
    { id: "spring-extra-20", question: "When should you use a Spring Data repository?", answer: "Use it when the repository abstraction expresses the aggregate's persistence needs clearly. Add explicit queries or a lower-level tool when generated methods hide an important performance or locking decision." },
    { id: "spring-extra-21", question: "What is the difference between a unit and integration test in Spring?", answer: "A unit test isolates a class with test doubles, while an integration test verifies collaboration with Spring, a database, or another real boundary. Use each for the risk it covers." },
    { id: "spring-extra-22", question: "What does @SpringBootTest do?", answer: "It loads a broad Spring application context for integration testing. It is useful for wiring and configuration checks but slower and less focused than a slice or unit test." },
    { id: "spring-extra-23", question: "When should you use a Spring test slice?", answer: "Use a slice such as web or data testing when you need a focused framework layer without loading the whole application. Mock or replace dependencies outside that slice." },
    { id: "spring-extra-24", question: "How do Spring Boot auto-configuration conditions work?", answer: "Boot creates configuration based on classpath entries, properties, and missing or existing beans. Condition evaluation reports help explain why a bean was or was not created." },
    { id: "spring-extra-25", question: "How do you resolve ambiguous Spring beans?", answer: "Prefer a clear primary implementation or inject a qualified named bean when multiple implementations are intentional. Avoid relying on registration order." },
    { id: "spring-extra-26", question: "What is an application event in Spring?", answer: "An application event communicates an in-process occurrence to listeners. Use it for decoupled local reactions, but use durable messaging when delivery must survive a process failure." },
    { id: "spring-extra-27", question: "What is Spring scheduling appropriate for?", answer: "It is suitable for local scheduled tasks where duplicate execution and recovery are controlled. Distributed jobs need coordination, idempotency, and a durable scheduling strategy." },
    { id: "spring-extra-28", question: "How do you configure timeouts for a Spring HTTP client?", answer: "Set connection, response, and overall operation deadlines in the client configuration, then test timeout behavior and resource release. A retry must respect the remaining request deadline." },
    { id: "spring-extra-29", question: "How do you protect a Spring endpoint from abuse?", answer: "Use authentication, authorization, input limits, rate limiting, timeouts, and audit logging appropriate to the endpoint. Keep secrets and sensitive response data out of logs." },
    { id: "spring-extra-30", question: "What is Spring Security's filter chain responsible for?", answer: "It processes web requests for concerns such as authentication, authorization, CSRF, and security context propagation. The chain order and matchers determine which rules apply." },
    { id: "spring-extra-31", question: "How should a Spring service handle a downstream timeout?", answer: "Translate it into a deliberate domain or API outcome, record useful context, and avoid retrying indefinitely. Use a fallback only when its data is safe and clearly marked." },
    { id: "spring-extra-32", question: "How do you make a Spring consumer idempotent?", answer: "Store a stable message or business key with processing status and enforce uniqueness, then return or safely repeat the prior result. Acknowledgment should follow durable handling." },
    { id: "spring-extra-33", question: "How do you avoid leaking persistence entities from a Spring API?", answer: "Map entities to response DTOs at the boundary. This controls fields, prevents lazy-loading surprises, and keeps database changes from becoming API changes." },
    { id: "spring-extra-34", question: "How do you manage database connection pool pressure?", answer: "Set pool size from measured database capacity, bound request concurrency, close connections through framework-managed transactions, and monitor acquisition wait time." },
    { id: "spring-extra-35", question: "How do you add health checks without hiding failures?", answer: "Separate liveness from readiness and include only dependencies whose failure should remove the instance from service. Keep checks fast and avoid exposing sensitive diagnostic details." },
    { id: "spring-extra-36", question: "How do you trace a request across Spring services?", answer: "Propagate a correlation or trace context through supported clients and include trace identifiers in structured logs. Sample and retain enough data to investigate important failures." },
    { id: "spring-extra-37", question: "How do you roll out a risky Spring configuration change?", answer: "Validate it in a production-like environment, use a feature flag or staged deployment, monitor relevant metrics, and keep a quick rollback path." },
    { id: "spring-extra-38", question: "How do you investigate a slow Spring endpoint?", answer: "Break latency into controller, application, database, downstream, queue, and serialization time using metrics and traces. Profile only after identifying the dominant segment." },
    { id: "spring-extra-39", question: "How do you design a reliable Spring event publication?", answer: "Persist the business change and an outbox record atomically, publish from a retryable worker, and make consumers idempotent. Monitor unpublished and failed records." },
    { id: "spring-extra-40", question: "How do you keep a Spring application maintainable at scale?", answer: "Organize by business capability, keep controllers thin, define transaction and integration boundaries, enforce dependency rules, and make operational behavior observable." },
  ],
  "aws": [
    { id: "aws-extra-01", question: "What is an AWS Region?", answer: "A Region is a geographic area containing multiple isolated Availability Zones. Choosing one affects latency, compliance, cost, and disaster recovery." },
    { id: "aws-extra-02", question: "What is an Availability Zone?", answer: "An Availability Zone is an isolated location within a Region with independent infrastructure. Deploying across zones reduces the impact of a single-zone failure." },
    { id: "aws-extra-03", question: "What is IAM used for?", answer: "IAM controls identities and permissions for AWS resources. Good policies grant only required actions on required resources under appropriate conditions." },
    { id: "aws-extra-04", question: "What is the difference between an IAM user and role?", answer: "A user is a long-lived identity, while a role is assumed to obtain temporary credentials. Workloads should generally use roles rather than embedded user keys." },
    { id: "aws-extra-05", question: "What does least privilege mean in AWS?", answer: "A principal receives only the permissions and resource scope needed for its task, for the shortest practical duration. Review and remove permissions as the system changes." },
    { id: "aws-extra-06", question: "What is an S3 bucket?", answer: "An S3 bucket stores objects identified by keys within a Region. Access, encryption, retention, and lifecycle behavior must be configured deliberately." },
    { id: "aws-extra-07", question: "How do S3 object and bucket policies differ?", answer: "A bucket policy is a resource policy governing access to the bucket and its objects, while an IAM policy is attached to an identity. The effective result depends on both and on explicit denies." },
    { id: "aws-extra-08", question: "What is S3 versioning for?", answer: "Versioning preserves prior object versions so accidental overwrites or deletes can be recovered. It can increase storage cost and requires lifecycle management." },
    { id: "aws-extra-09", question: "What is an S3 lifecycle rule?", answer: "It transitions or expires objects based on age, tags, or prefixes. Lifecycle rules reduce cost but must respect retention and recovery requirements." },
    { id: "aws-extra-10", question: "When would you use S3 instead of EBS?", answer: "Use S3 for durable object storage accessed through an API, and EBS for block storage attached to compute. They have different latency, access, and durability models." },
    { id: "aws-extra-11", question: "What is EC2?", answer: "EC2 provides virtual compute instances with selectable hardware, network, and storage characteristics. The customer manages more of the operating system and scaling than with serverless services." },
    { id: "aws-extra-12", question: "What is an Auto Scaling Group?", answer: "It maintains a desired number of instances and can adjust capacity based on policies or schedules. Instances must be replaceable and receive configuration automatically." },
    { id: "aws-extra-13", question: "What is an Application Load Balancer used for?", answer: "It distributes HTTP or HTTPS traffic across healthy targets and can route by host or path. Health checks should test useful readiness, not merely process existence." },
    { id: "aws-extra-14", question: "What is a VPC?", answer: "A VPC is a logically isolated network with subnets, routes, and security controls. It defines how workloads communicate with each other and external services." },
    { id: "aws-extra-15", question: "What is the difference between public and private subnets?", answer: "A public subnet has a route to an internet gateway, while a private subnet does not directly expose resources to the internet. Private workloads can use controlled egress through a NAT gateway." },
    { id: "aws-extra-16", question: "How do security groups work?", answer: "Security groups are stateful virtual firewalls attached to network interfaces and allow traffic through rules. Start with narrow sources, ports, and protocols." },
    { id: "aws-extra-17", question: "What is a network ACL?", answer: "A network ACL is a stateless subnet-level filter with ordered allow and deny rules. Security groups are usually the primary workload control, while ACLs add subnet-level boundaries." },
    { id: "aws-extra-18", question: "What is AWS Lambda?", answer: "Lambda runs functions in response to events without managing servers directly. Execution time, concurrency, cold starts, and downstream limits still require design." },
    { id: "aws-extra-19", question: "When is Lambda a poor fit?", answer: "It is a poor fit for long-running, highly stateful, consistently high-throughput work when container or instance economics and control are better. Check runtime, concurrency, and latency needs." },
    { id: "aws-extra-20", question: "What is Amazon ECS?", answer: "ECS orchestrates container workloads using a managed AWS control plane. It can run tasks on EC2 capacity or serverless Fargate capacity." },
    { id: "aws-extra-21", question: "What is the difference between SQS and SNS?", answer: "SQS is a durable queue consumed by workers, while SNS is a pub-sub notification service that can fan out messages to subscribers. They are often combined for independent consumers." },
    { id: "aws-extra-22", question: "What is a dead-letter queue?", answer: "A DLQ stores messages that exceed delivery attempts or cannot be processed. Operators can inspect, repair, and replay them after fixing the cause." },
    { id: "aws-extra-23", question: "What is EventBridge useful for?", answer: "EventBridge routes events between producers and consumers using event patterns and targets. It is useful for loosely coupled business events and scheduled rules." },
    { id: "aws-extra-24", question: "What is Amazon RDS?", answer: "RDS manages common relational database engines and automates tasks such as backups and patching. Schema design, query performance, and capacity remain application responsibilities." },
    { id: "aws-extra-25", question: "What is a read replica?", answer: "A read replica asynchronously copies data to serve read traffic or support reporting. It can lag and does not replace a high-availability or backup strategy." },
    { id: "aws-extra-26", question: "What is Multi-AZ deployment in RDS?", answer: "It maintains a synchronous standby in another Availability Zone for failover. It improves availability but is not primarily a read-scaling feature." },
    { id: "aws-extra-27", question: "When would you choose DynamoDB?", answer: "Choose it for predictable key-value or document access at large scale with a designed access pattern. It is not a drop-in relational database for arbitrary joins." },
    { id: "aws-extra-28", question: "What is a DynamoDB partition key?", answer: "It determines how items are distributed and located. A well-distributed key avoids hot partitions and supports the application's primary access patterns." },
    { id: "aws-extra-29", question: "What is CloudWatch used for?", answer: "CloudWatch collects metrics, logs, traces, alarms, and dashboards for AWS resources and applications. Alarms should measure actionable symptoms and capacity risks." },
    { id: "aws-extra-30", question: "What is AWS CloudTrail?", answer: "CloudTrail records AWS API activity for auditing, investigation, and governance. Protect and retain logs so an attacker cannot easily erase evidence." },
    { id: "aws-extra-31", question: "What is AWS KMS used for?", answer: "KMS manages encryption keys and cryptographic operations used by AWS services and applications. Key policies, rotation, access logging, and recovery must be planned." },
    { id: "aws-extra-32", question: "How should an AWS workload handle secrets?", answer: "Use Secrets Manager or a comparable managed store, grant access through workload roles, rotate credentials, and prevent values from entering logs or images." },
    { id: "aws-extra-33", question: "What is a CloudFront distribution?", answer: "CloudFront is a content delivery network that caches and serves content near users. Cache policy, invalidation, origin protection, and signed access affect correctness and security." },
    { id: "aws-extra-34", question: "What is the AWS shared responsibility model?", answer: "AWS secures the underlying cloud infrastructure, while customers secure their data, identities, configurations, and workloads according to the service used." },
    { id: "aws-extra-35", question: "How do you reduce AWS cost without reducing reliability blindly?", answer: "Use usage and cost data to right-size resources, remove waste, select suitable purchasing models, and improve storage or data-transfer efficiency. Preserve stated availability and recovery targets." },
    { id: "aws-extra-36", question: "How do you design disaster recovery across AWS Regions?", answer: "Define recovery time and data loss targets, replicate required data, automate infrastructure and failover, and test restoration. A second Region without a tested runbook is not a recovery plan." },
    { id: "aws-extra-37", question: "How do you secure a public AWS API?", answer: "Use HTTPS, authentication, authorization, validation, rate limits, WAF rules, private backends where possible, and centralized audit logs. Review data exposure separately from network exposure." },
    { id: "aws-extra-38", question: "How do you deploy an AWS service with low risk?", answer: "Use infrastructure as code, automated tests, staged or canary rollout, health-based rollback, and observable change metrics. Keep configuration and schema changes compatible during rollout." },
    { id: "aws-extra-39", question: "How do you investigate intermittent AWS latency?", answer: "Correlate application traces with load balancer, database, network, throttling, and downstream metrics across the affected time window. Compare zones and request classes before changing capacity." },
    { id: "aws-extra-40", question: "How do you decide between managed AWS services and self-managed infrastructure?", answer: "Compare operational ownership, control, cost, portability, compliance, performance, and team expertise. Prefer managed services when their constraints fit the requirements." },
  ],
  sql: [
    { id: "sql-extra-01", question: "What is a relational database table?", answer: "A table stores rows of related records under defined columns and constraints. Its schema describes allowed structure and relationships." },
    { id: "sql-extra-02", question: "What is a primary key?", answer: "A primary key uniquely identifies each row and should be stable and non-null. It also commonly supports the table's main lookup path." },
    { id: "sql-extra-03", question: "What is a foreign key?", answer: "A foreign key references a key in another table and enforces a relationship when configured. It prevents orphaned references and documents ownership." },
    { id: "sql-extra-04", question: "What is normalization?", answer: "Normalization organizes data to reduce duplication and update anomalies. Denormalization may be deliberate later for measured read performance." },
    { id: "sql-extra-05", question: "What does SELECT do?", answer: "SELECT reads columns and rows that match a query. Its result should specify ordering and pagination when clients depend on those properties." },
    { id: "sql-extra-06", question: "What is the difference between WHERE and HAVING?", answer: "WHERE filters rows before grouping, while HAVING filters groups after aggregation. Using WHERE earlier usually reduces work when the condition permits it." },
    { id: "sql-extra-07", question: "What does INNER JOIN return?", answer: "It returns rows with matching values on both sides of the join condition. Rows without a match are excluded." },
    { id: "sql-extra-08", question: "What does LEFT JOIN return?", answer: "It returns every row from the left table and matching rows from the right, using nulls when no match exists. Conditions on the right table need careful placement." },
    { id: "sql-extra-09", question: "What is an aggregate function?", answer: "Functions such as COUNT, SUM, MIN, and MAX combine values across rows or groups. NULL handling should be understood before interpreting the result." },
    { id: "sql-extra-10", question: "What does GROUP BY do?", answer: "GROUP BY forms groups of rows with equal grouping values so aggregate functions can calculate one result per group." },
    { id: "sql-extra-11", question: "What is an index?", answer: "An index is an additional data structure that can speed selected reads by avoiding a full scan. It consumes storage and adds write and maintenance cost." },
    { id: "sql-extra-12", question: "How do you choose columns for a composite index?", answer: "Start with common filters, joins, and ordering, then place useful selective and equality columns according to the query patterns. Verify with an execution plan." },
    { id: "sql-extra-13", question: "What is a covering index?", answer: "It contains all columns needed for a query so the database can answer it from the index without fetching table rows. It can improve reads at extra write and storage cost." },
    { id: "sql-extra-14", question: "What is a database transaction?", answer: "A transaction groups operations into a unit with defined commit or rollback behavior. Its boundary should match a business consistency requirement." },
    { id: "sql-extra-15", question: "What do ACID properties mean?", answer: "Atomicity groups changes, consistency preserves rules, isolation controls concurrent visibility, and durability preserves committed data. The database configuration and workload affect each guarantee." },
    { id: "sql-extra-16", question: "What is a dirty read?", answer: "A dirty read observes data written by a transaction that has not committed. An isolation level that prevents it trades some concurrency for consistency." },
    { id: "sql-extra-17", question: "What is a lost update?", answer: "Two writers read the same value and one overwrites the other's change. Optimistic version checks or appropriate locks prevent this race." },
    { id: "sql-extra-18", question: "What is optimistic locking?", answer: "A row includes a version or timestamp, and an update succeeds only if that value is unchanged since it was read. A conflict is reported for retry or resolution." },
    { id: "sql-extra-19", question: "What is pessimistic locking?", answer: "The database locks selected rows so conflicting transactions wait or fail. It can protect a short critical section but may reduce concurrency or cause deadlocks." },
    { id: "sql-extra-20", question: "What causes a deadlock in a database?", answer: "Transactions can each hold a lock the other needs, creating a cycle. Consistent lock order, short transactions, and retrying deadlock victims reduce the risk." },
    { id: "sql-extra-21", question: "What is an execution plan?", answer: "It describes how the database intends to access, join, filter, and sort data. Actual plans show whether estimates and runtime behavior match expectations." },
    { id: "sql-extra-22", question: "What is a full table scan?", answer: "It reads many or all table rows to evaluate a query. It can be correct for small tables or broad queries but becomes expensive as data grows." },
    { id: "sql-extra-23", question: "What is query parameterization?", answer: "It sends values separately from SQL structure, improving safety and often plan reuse. It prevents user input from being interpreted as SQL syntax." },
    { id: "sql-extra-24", question: "What is SQL injection?", answer: "SQL injection occurs when untrusted input changes a query's intended syntax. Parameterized queries, validation, and least-privilege database accounts prevent it." },
    { id: "sql-extra-25", question: "What is a view?", answer: "A view is a stored query exposed like a table. It can simplify or restrict access, but complex views may hide expensive execution and should be monitored." },
    { id: "sql-extra-26", question: "What is a materialized view?", answer: "It stores the result of a query and refreshes it on a schedule or trigger. It speeds repeated reads at the cost of freshness and refresh work." },
    { id: "sql-extra-27", question: "When should a table be partitioned?", answer: "Partition when data volume and access patterns make pruning, maintenance, or retention materially better. Partitioning is not a substitute for a suitable query and index design." },
    { id: "sql-extra-28", question: "What is database replication?", answer: "Replication copies data from one database node to another for availability, read scaling, or recovery. Asynchronous replicas can lag and should not be treated as immediately consistent." },
    { id: "sql-extra-29", question: "What is a read-after-write consistency issue?", answer: "A subsequent read may reach a lagging replica and not see a just-committed write. Route critical reads appropriately or expose consistency behavior explicitly." },
    { id: "sql-extra-30", question: "How do you paginate a large SQL result?", answer: "Keyset pagination uses a stable indexed cursor and scales better than large offsets. The sort must be deterministic and include a unique tie-breaker." },
    { id: "sql-extra-31", question: "What is a database migration?", answer: "It is a controlled schema or data change tracked with application releases. Migrations should be repeatable, observable, and compatible with rolling deployment." },
    { id: "sql-extra-32", question: "What is an expand-and-contract migration?", answer: "First add compatible schema, then deploy code using it, migrate data, and finally remove the old shape. This lets old and new application versions coexist." },
    { id: "sql-extra-33", question: "Why should large backfills run in batches?", answer: "Batches limit locks, transaction logs, replication lag, and resource spikes. They also provide checkpoints and a way to pause safely." },
    { id: "sql-extra-34", question: "What is a database constraint?", answer: "A constraint enforces a rule such as uniqueness, non-nullability, a foreign key, or a check. Put invariants in the database when it is the final shared authority." },
    { id: "sql-extra-35", question: "How do you model money in SQL?", answer: "Store a fixed-precision decimal with explicit currency rather than binary floating point. Define scale, rounding, and constraints consistently with application code." },
    { id: "sql-extra-36", question: "How do you audit changes to important records?", answer: "Record actor, action, time, request context, and before or after values in an append-oriented audit store. Protect its integrity and avoid storing unnecessary sensitive data." },
    { id: "sql-extra-37", question: "How do you diagnose a sudden database slowdown?", answer: "Check traffic, locks, wait events, connection pool saturation, query plans, storage, and recent changes. Compare the affected queries with a known healthy baseline." },
    { id: "sql-extra-38", question: "How do you design for database failover?", answer: "Use supported high-availability mechanisms, retry only safe transient failures, refresh connections after failover, and test the application during an actual controlled failover." },
    { id: "sql-extra-39", question: "How do you protect a database from a runaway query?", answer: "Use statement and transaction timeouts, resource limits, query review, appropriate indexes, and cancellation. Monitor expensive queries and keep a safe operational kill procedure." },
    { id: "sql-extra-40", question: "How do you decide whether to normalize or denormalize?", answer: "Normalize first for correctness and maintainability, then denormalize only for a measured workload bottleneck with a plan to keep duplicated data consistent." },
  ],
  "system-design": [
    { id: "system-design-extra-01", question: "What should you clarify before designing a system?", answer: "Clarify users, core use cases, scale, latency, availability, consistency, security, compliance, and cost constraints. State assumptions before choosing components." },
    { id: "system-design-extra-02", question: "What is horizontal scaling?", answer: "Horizontal scaling adds more instances to share work, while vertical scaling increases one instance's capacity. Horizontal scaling usually requires statelessness and coordination design." },
    { id: "system-design-extra-03", question: "What is vertical scaling?", answer: "Vertical scaling gives a machine more CPU, memory, or storage. It is simple but has an upper limit and can preserve a single failure boundary." },
    { id: "system-design-extra-04", question: "Why should application servers be stateless?", answer: "Stateless servers can be replaced, load-balanced, and scaled without moving user session data. State belongs in a deliberate shared store when it must survive requests." },
    { id: "system-design-extra-05", question: "What is a load balancer?", answer: "It distributes requests across healthy backend instances and can terminate TLS or route by request properties. It must have meaningful health and timeout behavior." },
    { id: "system-design-extra-06", question: "What is caching in system design?", answer: "Caching stores reusable results closer to consumers to reduce latency and backend load. The design must define freshness, invalidation, capacity, and failure behavior." },
    { id: "system-design-extra-07", question: "What is cache-aside?", answer: "The application reads the cache first, loads from the source on a miss, and then populates the cache. It must handle stampedes, stale values, and failed writes." },
    { id: "system-design-extra-08", question: "What is cache invalidation?", answer: "It removes or updates cached data when the source changes. TTLs are simple but may serve stale values, while event-driven invalidation needs reliable propagation." },
    { id: "system-design-extra-09", question: "What is a cache stampede?", answer: "Many requests miss or expire the same key and overload the source simultaneously. Jittered TTLs, request coalescing, and stale-while-revalidate can reduce it." },
    { id: "system-design-extra-10", question: "What is a message queue?", answer: "A queue buffers work between producers and consumers and enables retry or independent scaling. Delivery semantics and duplicate handling must be explicit." },
    { id: "system-design-extra-11", question: "What is at-least-once delivery?", answer: "A message is delivered one or more times, so consumers must tolerate duplicates. It favors not losing work over avoiding every duplicate." },
    { id: "system-design-extra-12", question: "What is exactly-once processing?", answer: "It means the intended effect occurs once, even if delivery or execution is retried. It usually requires idempotency and durable coordination rather than a simple broker setting." },
    { id: "system-design-extra-13", question: "What is a partition key?", answer: "It determines where a record or request is distributed in a sharded system. A good key balances load while supporting the main access pattern." },
    { id: "system-design-extra-14", question: "What is a hot partition?", answer: "A hot partition receives disproportionate traffic or data because its key distribution is skewed. It can become a throughput bottleneck despite spare capacity elsewhere." },
    { id: "system-design-extra-15", question: "What is consistent hashing?", answer: "It maps keys and nodes around a hash ring so adding or removing a node moves only part of the key space. Virtual nodes improve balance." },
    { id: "system-design-extra-16", question: "What is rate limiting?", answer: "Rate limiting bounds requests or work for a client or resource over time. It protects capacity and should return a clear retry signal when possible." },
    { id: "system-design-extra-17", question: "What is a token bucket rate limiter?", answer: "Tokens accumulate up to a cap and each request consumes tokens, allowing controlled bursts while limiting long-term rate. The bucket state must be coordinated when distributed." },
    { id: "system-design-extra-18", question: "What is a CDN?", answer: "A CDN caches content at edge locations near users and reduces origin traffic. Cache headers, invalidation, and private-content authorization determine correctness." },
    { id: "system-design-extra-19", question: "What is a single point of failure?", answer: "It is a component whose failure can take down the required service. Remove it through redundancy or explicitly accept and document the risk." },
    { id: "system-design-extra-20", question: "What is graceful degradation?", answer: "It preserves essential behavior while reducing or disabling optional behavior during a dependency or capacity failure. The reduced experience should be observable and understandable." },
    { id: "system-design-extra-21", question: "What is a health check?", answer: "It tests whether a component is alive or ready to receive work. Liveness should detect process failure, while readiness should include required service capability." },
    { id: "system-design-extra-22", question: "What is a heartbeat?", answer: "A heartbeat is a periodic signal that indicates a node or connection is still active. Timeouts must account for network delay and temporary load." },
    { id: "system-design-extra-23", question: "How do you design an idempotent API?", answer: "Accept a client-provided idempotency key, store its request identity and result, and return the same result for a safe retry. Enforce a uniqueness rule at the durable boundary." },
    { id: "system-design-extra-24", question: "How do you handle a large file upload?", answer: "Upload directly to object storage with a short-lived authorization, then validate size, type, ownership, and scan status before publishing the file." },
    { id: "system-design-extra-25", question: "How do you design a notification system?", answer: "Separate preference and template decisions from channel delivery, queue work, retry transient failures, and record provider outcomes. Make each notification operation idempotent." },
    { id: "system-design-extra-26", question: "How do you design a search feature?", answer: "Define fields, relevance, freshness, filters, and tolerable indexing lag, then choose a store that supports them. Keep the source of truth separate from the search index." },
    { id: "system-design-extra-27", question: "How do you design a URL shortener?", answer: "Generate a unique short key, store the mapping durably, cache popular redirects, and rate-limit creation and lookup abuse. Define expiration and collision behavior." },
    { id: "system-design-extra-28", question: "How do you design a leaderboard?", answer: "Choose a ranking store that supports updates and ordered reads, define tie handling, and separate hot current rankings from historical data. Verify write contention at expected scale." },
    { id: "system-design-extra-29", question: "How do you design an audit log?", answer: "Emit immutable records containing actor, action, target, time, request context, and outcome. Restrict access and make retention and search requirements explicit." },
    { id: "system-design-extra-30", question: "How do you design for multi-tenancy?", answer: "Choose tenant isolation, include tenant identity in authorization and data access, and prevent cross-tenant queries through constraints and tests. Define noisy-neighbor controls." },
    { id: "system-design-extra-31", question: "What is a quorum?", answer: "A quorum is the minimum number of replicas that must acknowledge an operation for it to proceed. It trades availability, latency, and consistency based on the chosen read and write counts." },
    { id: "system-design-extra-32", question: "What is the CAP tradeoff?", answer: "When a network partition occurs, a distributed system must trade between consistency and availability for affected operations. It does not mean a system simply chooses two permanent letters." },
    { id: "system-design-extra-33", question: "How do you estimate capacity?", answer: "Start with request rates, payload sizes, concurrency, storage growth, and dependency limits, then validate assumptions with load tests and production measurements." },
    { id: "system-design-extra-34", question: "How do you design for backpressure?", answer: "Bound queues and concurrency, expose overload signals, shed or defer noncritical work, and preserve a path for recovery. Unbounded buffering only hides saturation." },
    { id: "system-design-extra-35", question: "How do you handle clock differences across services?", answer: "Use synchronized clocks for timestamps, avoid relying on local time for ordering, and use logical or database sequence values when strict ordering matters." },
    { id: "system-design-extra-36", question: "How do you design a rolling deployment?", answer: "Keep old and new versions compatible, drain instances safely, migrate schema in phases, monitor health and business metrics, and stop or roll back on defined thresholds." },
    { id: "system-design-extra-37", question: "How do you choose a consistency model?", answer: "Map each use case to the stale data and conflict it can tolerate, then choose the simplest model that preserves its invariant. Explain user-visible consequences." },
    { id: "system-design-extra-38", question: "How do you design disaster recovery?", answer: "Set recovery time and data loss targets, replicate or back up required state, automate restoration, and rehearse failover and rollback with operators." },
    { id: "system-design-extra-39", question: "How do you review a system design for operational risk?", answer: "Trace dependency failures, capacity limits, deploys, data recovery, observability, access control, and ownership. Ask how an on-call engineer will detect and repair each failure." },
    { id: "system-design-extra-40", question: "How do you explain a system design tradeoff in an interview?", answer: "State the requirement, give the chosen design, name the main alternative, and explain what the choice optimizes and sacrifices. Include the failure mode you would address next." },
  ],
  leadership: [
    { id: "leadership-extra-01", question: "What is the core responsibility of a technical lead?", answer: "A technical lead creates clarity, raises engineering quality, and helps the team deliver valuable work sustainably. The role is influence and ownership, not personal control of every decision." },
    { id: "leadership-extra-02", question: "How do you build trust with a new team?", answer: "Listen first, make commitments reliably, explain decisions, give credit, and address problems directly. Trust grows from consistent behavior rather than a single team activity." },
    { id: "leadership-extra-03", question: "How do you set expectations for a team?", answer: "Make outcomes, ownership, decision rights, quality standards, and communication norms explicit. Check understanding and revise expectations when constraints change." },
    { id: "leadership-extra-04", question: "How do you delegate effectively?", answer: "Delegate an outcome with context, authority, constraints, and a check-in point, then let the owner decide within that boundary. Delegation is not merely assigning tasks." },
    { id: "leadership-extra-05", question: "How do you run a one-on-one meeting?", answer: "Use it for the person's goals, obstacles, feedback, and support rather than a status report. Listen more than you speak and follow through on agreed actions." },
    { id: "leadership-extra-06", question: "How do you coach a junior engineer?", answer: "Set a reachable goal, explain the reasoning behind practices, give them ownership of a bounded problem, and provide timely specific feedback." },
    { id: "leadership-extra-07", question: "How do you support a senior engineer who is stuck?", answer: "Clarify the decision or constraint, ask what options they have considered, and help remove organizational blockers without taking ownership away unnecessarily." },
    { id: "leadership-extra-08", question: "How do you handle disagreement in a design review?", answer: "Separate the person from the proposal, restate the shared goal, compare evidence and tradeoffs, and decide who owns the final call. Record unresolved assumptions." },
    { id: "leadership-extra-09", question: "How do you make a decision with incomplete information?", answer: "Identify the reversible and irreversible parts, state assumptions, gather the cheapest useful evidence, and choose a bounded experiment when possible." },
    { id: "leadership-extra-10", question: "How do you communicate an unpopular technical decision?", answer: "Explain the context, options, evidence, consequences, and what feedback was considered. Once decided, help the team execute while keeping a trigger for revisiting it." },
    { id: "leadership-extra-11", question: "How do you protect engineering quality under deadline pressure?", answer: "Separate essential quality and safety work from polish, make risks visible, reduce scope before lowering critical standards, and agree on a dated follow-up for accepted debt." },
    { id: "leadership-extra-12", question: "How do you prioritize technical debt?", answer: "Rank it by user or delivery impact, failure probability, change friction, and cost of delay. Fund the items that reduce meaningful risk or unlock important work." },
    { id: "leadership-extra-13", question: "How do you handle a teammate who dominates meetings?", answer: "Set an explicit facilitation norm, interrupt respectfully when needed, invite quieter people by name, and discuss the pattern privately with specific examples." },
    { id: "leadership-extra-14", question: "How do you include remote or quiet teammates in decisions?", answer: "Share context before meetings, allow asynchronous input, use written decision records, and ensure speaking time does not determine whose ideas are considered." },
    { id: "leadership-extra-15", question: "How do you address repeated missed commitments?", answer: "Discuss the behavior privately, understand constraints, clarify the commitment, and agree on a measurable change. Escalate support or accountability if the pattern continues." },
    { id: "leadership-extra-16", question: "How do you give difficult feedback?", answer: "Describe observable behavior, impact, and the expected change, then listen to context and agree on follow-up. Give it promptly and privately." },
    { id: "leadership-extra-17", question: "How do you receive feedback as a lead?", answer: "Listen without defending immediately, ask for examples, thank the person, and choose a visible behavior to change. Follow up to show what happened." },
    { id: "leadership-extra-18", question: "How do you handle conflict between two engineers?", answer: "Meet with each person to understand facts, then bring them together around the shared outcome and specific behaviors. Agree on a decision and working agreement." },
    { id: "leadership-extra-19", question: "How do you respond to an incident as a lead?", answer: "Prioritize user impact, establish roles and communication cadence, protect responders from blame, and lead a blameless learning review after recovery." },
    { id: "leadership-extra-20", question: "What makes a retrospective useful?", answer: "It focuses on system conditions and actionable changes, not assigning blame. Each action needs an owner, a small scope, and a way to verify improvement." },
    { id: "leadership-extra-21", question: "How do you align engineering and product?", answer: "Translate technical constraints into user impact, discuss options and cost, and agree on outcomes and tradeoffs together. Avoid presenting estimates as promises detached from scope." },
    { id: "leadership-extra-22", question: "How do you manage scope during a project?", answer: "Define the essential outcome, make dependencies and risks visible, and cut optional work before compressing quality or recovery time." },
    { id: "leadership-extra-23", question: "How do you improve estimation accuracy?", answer: "Split work around uncertainty, use historical delivery data, state assumptions, and update estimates when evidence changes. Do not use estimates as individual performance rankings." },
    { id: "leadership-extra-24", question: "How do you create ownership without silos?", answer: "Assign clear decision and operational ownership while keeping interfaces, documentation, and review paths open. Ownership means accountability, not exclusive knowledge." },
    { id: "leadership-extra-25", question: "How do you reduce bus factor risk?", answer: "Rotate responsibilities, pair on critical areas, document operational knowledge, and make ownership shared through reviews and practice." },
    { id: "leadership-extra-26", question: "How do you mentor someone toward promotion?", answer: "Clarify the target expectations, identify evidence gaps, create opportunities to demonstrate the next level, and give regular feedback against those expectations." },
    { id: "leadership-extra-27", question: "How do you recognize good work fairly?", answer: "Connect recognition to specific impact and behaviors, include behind-the-scenes contributions, and use consistent criteria rather than rewarding only visibility or overtime." },
    { id: "leadership-extra-28", question: "How do you handle an underperforming teammate?", answer: "Confirm the expectations and observable gap, ask about support needs, create a documented improvement plan, and involve the appropriate manager process when needed." },
    { id: "leadership-extra-29", question: "How do you lead through organizational change?", answer: "Share what is known and unknown, explain the reason and impact, invite questions, and keep commitments realistic. People need clarity more than false certainty." },
    { id: "leadership-extra-30", question: "How do you resolve a priority conflict between stakeholders?", answer: "Bring the competing outcomes, deadlines, risks, and capacity into one discussion, then ask the accountable product or business owner to make the tradeoff explicit." },
    { id: "leadership-extra-31", question: "How do you build a healthy code review culture?", answer: "Set review goals around correctness, maintainability, and learning, keep comments respectful and specific, and use automation for mechanical checks." },
    { id: "leadership-extra-32", question: "How do you decide when to pair program?", answer: "Pair when the problem is ambiguous, risky, or a learning opportunity; work independently when tasks are clear and parallelism is valuable." },
    { id: "leadership-extra-33", question: "How do you protect team focus?", answer: "Limit work in progress, clarify interrupt ownership, reserve time for deep work, and make priority changes visible instead of adding invisible work." },
    { id: "leadership-extra-34", question: "How do you handle a mistake made by a team member?", answer: "Stabilize the impact, understand the contributing system conditions, support the person, and improve the process or guardrail. Avoid public blame." },
    { id: "leadership-extra-35", question: "How do you build psychological safety?", answer: "Respond to questions and bad news with curiosity, admit your own uncertainty, protect respectful dissent, and address behavior that silences others." },
    { id: "leadership-extra-36", question: "How do you lead a team across time zones?", answer: "Use asynchronous decisions, documented handoffs, overlap for high-bandwidth work, and predictable response expectations. Do not make availability the measure of commitment." },
    { id: "leadership-extra-37", question: "How do you decide whether to escalate a problem?", answer: "Escalate when impact exceeds your authority, time, or risk tolerance, and bring facts, options, and a specific decision or support request." },
    { id: "leadership-extra-38", question: "How do you measure team health?", answer: "Combine delivery reliability, quality, incident load, retention signals, and direct team feedback. Avoid reducing health to velocity or hours worked." },
    { id: "leadership-extra-39", question: "How do you balance autonomy and alignment?", answer: "Align on outcomes, constraints, principles, and decision boundaries, then let the closest capable person choose the implementation." },
    { id: "leadership-extra-40", question: "What does servant leadership mean in engineering?", answer: "It means removing blockers, growing people, clarifying context, and creating conditions for the team to make good decisions. It does not mean avoiding accountability." },
  ],
  concurrency: [
    { id: "concurrency-extra-01", question: "What is concurrency?", answer: "Concurrency means multiple tasks can make progress during overlapping periods. It differs from parallelism, which executes work simultaneously on multiple processors." },
    { id: "concurrency-extra-02", question: "What is a race condition?", answer: "A race condition occurs when the result depends on unpredictable timing between operations. Shared state needs synchronization or a design that removes the race." },
    { id: "concurrency-extra-03", question: "What is a data race?", answer: "A data race is unsynchronized concurrent access to the same memory where at least one access writes. It can produce undefined or surprising observations under the memory model." },
    { id: "concurrency-extra-04", question: "What is atomicity?", answer: "Atomicity means an operation appears indivisible to other threads. A read-modify-write sequence is not automatically atomic just because each individual access is simple." },
    { id: "concurrency-extra-05", question: "What is visibility between threads?", answer: "Visibility means one thread eventually observes another thread's write according to synchronization rules. Locks, volatile, and concurrency utilities establish the required ordering." },
    { id: "concurrency-extra-06", question: "What is a critical section?", answer: "A critical section is code that accesses shared state and must not interleave unsafely with another execution. Keep it small and protect it with an appropriate mechanism." },
    { id: "concurrency-extra-07", question: "What does a mutex provide?", answer: "A mutex permits one owner at a time to enter a protected section. The owner must release it reliably, including on exceptional paths." },
    { id: "concurrency-extra-08", question: "What is a semaphore?", answer: "A semaphore controls access to a limited number of permits, such as connections or concurrent calls. It is not interchangeable with a lock protecting one invariant." },
    { id: "concurrency-extra-09", question: "What is a deadlock?", answer: "A deadlock occurs when tasks wait forever for resources held by one another. Consistent acquisition order, timeouts, and smaller critical sections reduce risk." },
    { id: "concurrency-extra-10", question: "What is livelock?", answer: "In a livelock, tasks keep reacting to each other but make no useful progress. Randomized backoff or a clearer ownership rule can break the cycle." },
    { id: "concurrency-extra-11", question: "What is starvation?", answer: "Starvation occurs when a task repeatedly cannot obtain the resource or scheduling time it needs. Fairness, bounded work, and capacity policies can help." },
    { id: "concurrency-extra-12", question: "What is a thread pool?", answer: "A thread pool reuses a bounded set of threads to execute tasks. Bounded queues and rejection behavior prevent unlimited work from exhausting resources." },
    { id: "concurrency-extra-13", question: "Why can an unbounded executor queue be dangerous?", answer: "It accepts work faster than it can complete, growing memory and latency until the process fails. Backpressure or bounded rejection makes overload visible." },
    { id: "concurrency-extra-14", question: "What is a producer-consumer pattern?", answer: "Producers create work and consumers process it through a queue or buffer. The buffer decouples rates but needs capacity and overload behavior." },
    { id: "concurrency-extra-15", question: "What is a blocking operation?", answer: "It prevents a thread or task from continuing until an event completes, such as I/O or a lock. Blocking can be acceptable when capacity and deadlines are bounded." },
    { id: "concurrency-extra-16", question: "What is nonblocking I/O?", answer: "Nonblocking I/O lets a thread handle other work while an operation waits for readiness. It can improve scalability but requires an event-driven programming model." },
    { id: "concurrency-extra-17", question: "What is an atomic variable?", answer: "It provides atomic operations and visibility for supported values without a separate explicit lock. Compound business invariants may still need a lock or transaction." },
    { id: "concurrency-extra-18", question: "What is compare-and-set?", answer: "Compare-and-set updates a value only if it still equals an expected value. It enables lock-free algorithms but can suffer retries and is difficult for multi-field invariants." },
    { id: "concurrency-extra-19", question: "What is immutability's concurrency benefit?", answer: "Immutable state cannot be changed after publication, so readers can share it without coordination. Construction and safe publication still must be correct." },
    { id: "concurrency-extra-20", question: "What is thread confinement?", answer: "Thread confinement keeps mutable state owned by one thread so no synchronization is needed for it. Request-local state and some event-loop designs use this approach." },
    { id: "concurrency-extra-21", question: "What is a concurrent map useful for?", answer: "It provides safe concurrent map operations with better coordination than synchronizing every access to an ordinary map. Compound workflows still need atomic map methods or external coordination." },
    { id: "concurrency-extra-22", question: "What is a barrier?", answer: "A barrier makes a group of tasks wait until all required participants reach a point. It is useful for phased parallel work, not indefinite producer-consumer flows." },
    { id: "concurrency-extra-23", question: "What is a countdown latch?", answer: "A latch lets one or more threads wait until a fixed number of completions occur. It is one-use synchronization and should have a timeout where failure is possible." },
    { id: "concurrency-extra-24", question: "What is cancellation in concurrent work?", answer: "Cancellation requests that work stop, but the task must cooperate by checking status and handling interruption. Cancellation should release resources and produce a defined outcome." },
    { id: "concurrency-extra-25", question: "Why is interrupt status important in Java?", answer: "Interruption is a cooperative signal for blocking or long-running work. Code that catches InterruptedException should usually restore the status or propagate cancellation." },
    { id: "concurrency-extra-26", question: "What is a future?", answer: "A future represents a result that may complete later and can expose success, failure, or cancellation. Blocking on it still consumes capacity and needs a deadline." },
    { id: "concurrency-extra-27", question: "How do you avoid blocking inside an async pipeline?", answer: "Use nonblocking APIs or isolate unavoidable blocking work on a bounded dedicated executor. Keep the pipeline's deadline and error propagation explicit." },
    { id: "concurrency-extra-28", question: "How do you make a check-then-act operation safe?", answer: "Combine the check and mutation in one atomic database operation, lock the protected state, or use compare-and-set. Separate unsynchronized steps are vulnerable to interleaving." },
    { id: "concurrency-extra-29", question: "How do you prevent duplicate scheduled jobs across instances?", answer: "Use a distributed lock or a scheduler with ownership semantics, and make the job idempotent. A local in-memory flag is insufficient in a cluster." },
    { id: "concurrency-extra-30", question: "How do you limit concurrent calls to a partner?", answer: "Use a semaphore or bounded bulkhead around the client, with timeouts and a clear rejection path. Monitor permits, wait time, and partner errors." },
    { id: "concurrency-extra-31", question: "How do you test a concurrency bug?", answer: "Create a small deterministic stress or coordination test that forces the suspected interleaving, then run it repeatedly with diagnostics. Confirm the invariant rather than relying only on timing." },
    { id: "concurrency-extra-32", question: "How do you diagnose thread starvation?", answer: "Inspect thread dumps, pool queue depth, active counts, blocking calls, and task duration. Identify which workload consumes capacity and whether deadlines are missing." },
    { id: "concurrency-extra-33", question: "How do you diagnose deadlocks in Java?", answer: "Capture thread dumps and lock ownership, identify the wait cycle, then enforce lock ordering or reduce nested locking. Add timeouts or metrics for future detection." },
    { id: "concurrency-extra-34", question: "What is structured concurrency useful for?", answer: "It keeps child tasks within a parent scope so cancellation, failure, and lifetime are explicit. This prevents abandoned work after a request has ended." },
    { id: "concurrency-extra-35", question: "When do virtual threads help concurrency?", answer: "They allow many mostly blocking tasks to wait with lower platform-thread cost. They do not remove CPU, database, memory, or downstream capacity limits." },
    { id: "concurrency-extra-36", question: "How do you coordinate a multi-step concurrent workflow?", answer: "Define task dependencies, cancellation rules, deadlines, partial failure behavior, and result aggregation before choosing futures or queues." },
    { id: "concurrency-extra-37", question: "How do you handle concurrent updates to inventory?", answer: "Enforce the stock invariant atomically in the database or a correctly synchronized owner, then make retries idempotent. An application-only check is not enough." },
    { id: "concurrency-extra-38", question: "What is false sharing?", answer: "False sharing occurs when independent variables share a CPU cache line and updates cause unnecessary cache invalidation. It matters in carefully optimized high-throughput code and requires measurement." },
    { id: "concurrency-extra-39", question: "When is lock-free programming justified?", answer: "Use it only when measured contention and latency requirements justify its complexity and the algorithm can be proven correct. Simpler locks are usually easier to maintain." },
    { id: "concurrency-extra-40", question: "How do you review a concurrent design?", answer: "List shared state, ownership, atomic invariants, visibility guarantees, resource bounds, cancellation, ordering, and failure behavior. Then test the highest-risk interleavings." },
  ],
  "testing-quality": [
    { id: "testing-quality-extra-01", question: "Why do teams write automated tests?", answer: "Tests provide repeatable evidence that behavior works and protect it during change. They also expose unclear contracts and design coupling." },
    { id: "testing-quality-extra-02", question: "What is a unit test?", answer: "A unit test verifies a small unit of behavior in isolation from slow or unreliable boundaries. Its speed makes it useful for frequent feedback." },
    { id: "testing-quality-extra-03", question: "What is an integration test?", answer: "An integration test verifies that components work together through a real boundary such as a database, queue, or framework context." },
    { id: "testing-quality-extra-04", question: "What is an end-to-end test?", answer: "It exercises a user-relevant flow across most or all production-like layers. It gives broad confidence but is slower and more failure-prone to diagnose." },
    { id: "testing-quality-extra-05", question: "What is a test double?", answer: "A test double replaces a dependency in a test; common forms include stubs, mocks, fakes, and spies. Choose the least behavior-sensitive double that fits the risk." },
    { id: "testing-quality-extra-06", question: "What is the difference between a stub and a mock?", answer: "A stub supplies controlled answers, while a mock also verifies expected interactions. Prefer testing observable outcomes unless the interaction is itself the contract." },
    { id: "testing-quality-extra-07", question: "What makes a test deterministic?", answer: "It controls time, randomness, external state, concurrency, and data setup so the same behavior produces the same result. Determinism improves trust in failures." },
    { id: "testing-quality-extra-08", question: "What is a flaky test?", answer: "A flaky test sometimes passes or fails without a relevant code change. Investigate timing, shared state, ordering, environment, and cleanup instead of rerunning forever." },
    { id: "testing-quality-extra-09", question: "What is test isolation?", answer: "Each test can run independently without depending on another test's state, order, or side effects. Isolated setup and cleanup make failures local." },
    { id: "testing-quality-extra-10", question: "Why should tests have one clear reason to fail?", answer: "A focused test maps a failure to a small behavior and speeds diagnosis. It need not have one assertion, but it should verify one coherent outcome." },
    { id: "testing-quality-extra-11", question: "What is a test fixture?", answer: "A fixture is the setup data and environment needed for a test. Keep fixtures minimal and representative so tests remain readable and meaningful." },
    { id: "testing-quality-extra-12", question: "What is property-based testing?", answer: "It generates many inputs to check a general property rather than only selected examples. It is useful for parsers, transformations, and invariant-heavy logic." },
    { id: "testing-quality-extra-13", question: "What is contract testing?", answer: "It verifies that a provider and consumer agree on an interface, payload, and relevant behavior. It reduces reliance on slow full-system tests for service integrations." },
    { id: "testing-quality-extra-14", question: "What is mutation testing?", answer: "Mutation testing changes code in small ways and checks whether tests detect those changes. It reveals suites that execute code without protecting behavior." },
    { id: "testing-quality-extra-15", question: "What is code coverage?", answer: "Coverage measures which code or branches tests execute, but execution alone does not prove assertions are meaningful. Use it as a signal alongside risk and defect history." },
    { id: "testing-quality-extra-16", question: "How do you test error handling?", answer: "Trigger each important failure condition and verify status, safe message, state changes, logging context, and retry behavior. Include dependency timeout and malformed input cases." },
    { id: "testing-quality-extra-17", question: "How do you test time-dependent code?", answer: "Inject a clock or scheduler and advance it explicitly in tests. Avoid sleeping, which makes tests slow and timing-sensitive." },
    { id: "testing-quality-extra-18", question: "How do you test code using randomness?", answer: "Inject a random source or seed a controlled generator, then test both representative outcomes and boundary behavior. Do not rely on a lucky random run." },
    { id: "testing-quality-extra-19", question: "How do you test database code reliably?", answer: "Use a production-compatible database in focused integration tests, isolate data per test or transaction, and verify constraints and query behavior rather than mocking SQL." },
    { id: "testing-quality-extra-20", question: "How do you test an external HTTP client?", answer: "Use contract or controlled server tests for serialization, status mapping, timeouts, and retries. Keep a small number of live checks for provider compatibility." },
    { id: "testing-quality-extra-21", question: "What is a regression test?", answer: "It captures a previously fixed defect so the same behavior does not return. The test should fail for the original defect and pass for the corrected behavior." },
    { id: "testing-quality-extra-22", question: "What is a smoke test?", answer: "A smoke test checks that a deployed system starts and its most essential path works. It is broad and shallow, so it does not replace deeper tests." },
    { id: "testing-quality-extra-23", question: "What is risk-based testing?", answer: "It allocates testing effort according to impact, likelihood, complexity, and change risk. Critical money or security paths deserve stronger evidence than trivial formatting." },
    { id: "testing-quality-extra-24", question: "How do you test authorization?", answer: "Test allowed roles and resources plus explicit denial cases, including cross-user and cross-tenant access. Verify that denied requests do not mutate state or leak data." },
    { id: "testing-quality-extra-25", question: "How do you test a retry policy?", answer: "Simulate transient, permanent, and timeout failures and verify attempt count, backoff bounds, jitter, deadline, and final outcome. Confirm non-idempotent work is not duplicated." },
    { id: "testing-quality-extra-26", question: "How do you test concurrent behavior?", answer: "Coordinate threads to force important interleavings, assert invariants, and run stress tests under representative load. Avoid tests that pass only because of arbitrary sleeps." },
    { id: "testing-quality-extra-27", question: "How do you test an asynchronous message consumer?", answer: "Publish controlled messages, wait on an observable completion condition, and verify side effects, acknowledgment, retry, and duplicate handling. Keep timeouts bounded." },
    { id: "testing-quality-extra-28", question: "What belongs in a CI quality gate?", answer: "Use fast compilation, unit tests, relevant integration tests, static checks, security checks, and artifact validation. Gates should be reliable and tied to meaningful risk." },
    { id: "testing-quality-extra-29", question: "How do you handle a failing test in CI?", answer: "Classify it as product failure, test defect, environment issue, or flake, then fix the cause and preserve evidence. Do not normalize rerunning until green." },
    { id: "testing-quality-extra-30", question: "How do you make a test suite faster?", answer: "Measure slow tests, remove unnecessary setup, use focused boundaries, parallelize safely, and replace sleeps with signals. Keep high-value integration coverage." },
    { id: "testing-quality-extra-31", question: "How do you test backward compatibility?", answer: "Run old clients or contract fixtures against the new provider and test old data shapes and migrations. Define which changes are allowed before implementation." },
    { id: "testing-quality-extra-32", question: "How do you test a data migration?", answer: "Use realistic volume and edge cases, verify counts and invariants before and after, test restart or partial failure, and measure lock and runtime impact." },
    { id: "testing-quality-extra-33", question: "What is exploratory testing?", answer: "It is structured investigation guided by hypotheses and observations rather than only scripted cases. It is valuable for discovering unexpected workflows and usability risks." },
    { id: "testing-quality-extra-34", question: "How do you review a test for quality?", answer: "Check that it fails for the wrong behavior, asserts meaningful outcomes, controls external state, and avoids coupling to incidental implementation details." },
    { id: "testing-quality-extra-35", question: "What is testability in design?", answer: "Testability means important behavior can be observed and controlled without excessive setup or hidden effects. Clear boundaries and dependency injection improve it." },
    { id: "testing-quality-extra-36", question: "How do you balance mocks and real dependencies?", answer: "Mock stable external boundaries in unit tests, and use real compatible dependencies where integration behavior is the risk. Too many mocks can verify an imaginary implementation." },
    { id: "testing-quality-extra-37", question: "How do you test observability?", answer: "Verify important metrics, structured fields, trace propagation, and safe error logs in representative failure paths. Observability that cannot support an investigation is incomplete." },
    { id: "testing-quality-extra-38", question: "How do you measure release quality?", answer: "Track escaped defects, rollback rate, change failure rate, incident impact, and time to recovery alongside test results. No single metric proves quality." },
    { id: "testing-quality-extra-39", question: "How do you improve quality in a legacy system with few tests?", answer: "Start with characterization tests around high-risk behavior, add seams at boundaries, fix defects with regression tests, and improve coverage as features change." },
    { id: "testing-quality-extra-40", question: "What is your quality strategy for a critical feature?", answer: "Combine clear acceptance criteria, focused unit tests, boundary integration tests, security and failure cases, production observability, staged rollout, and a recovery plan." },
  ],
  behavioral: [
    { id: "behavioral-extra-01", question: "Tell me about a time you solved a difficult problem at work.", answer: "Use STAR: describe the context, your specific responsibility, the actions you took, and a measurable result. Keep the story focused on your reasoning and outcome." },
    { id: "behavioral-extra-02", question: "Tell me about a time you resolved a conflict with a coworker.", answer: "Explain the shared goal, the disagreement, how you listened and used facts, the agreement reached, and what improved afterward. Avoid making the other person a villain." },
    { id: "behavioral-extra-03", question: "Tell me about a time you failed.", answer: "Choose a real but bounded failure, own your part, explain the impact, and describe the process change that prevented recurrence. End with evidence that you learned." },
    { id: "behavioral-extra-04", question: "Tell me about a time you received difficult feedback.", answer: "State the feedback without defensiveness, explain what you changed, and give a later result. The strongest answer shows a sustained behavior change." },
    { id: "behavioral-extra-05", question: "Tell me about a time you had to prioritize competing tasks.", answer: "Describe the competing outcomes and constraints, explain how you assessed impact and urgency, communicate the tradeoff, and report what was delivered." },
    { id: "behavioral-extra-06", question: "Tell me about a time you led without formal authority.", answer: "Show how you built alignment through context, listening, evidence, and clear ownership. Include the team or business result rather than claiming personal control." },
    { id: "behavioral-extra-07", question: "Tell me about a time you helped a teammate succeed.", answer: "Describe the teammate's goal, the support you provided without taking over, and the result. Mention how you encouraged their independent capability." },
    { id: "behavioral-extra-08", question: "Tell me about a time you worked with someone from a different background.", answer: "Focus on curiosity, inclusive communication, and adapting collaboration to the person's needs. Explain the outcome without making assumptions about their identity." },
    { id: "behavioral-extra-09", question: "Tell me about a time you challenged an unethical decision.", answer: "Explain the risk and the respectful channel you used, document relevant facts, and describe how you protected users or colleagues. Do not disclose confidential details." },
    { id: "behavioral-extra-10", question: "Tell me about a time you made a decision with incomplete information.", answer: "State the unknowns, the evidence you gathered, the reversible step you chose, and how you monitored the result. Show when you would have changed course." },
    { id: "behavioral-extra-11", question: "Tell me about a time you had to meet a tight deadline.", answer: "Explain how you defined the essential outcome, reduced scope or risk, coordinated dependencies, and protected critical quality. Give the actual result." },
    { id: "behavioral-extra-12", question: "Tell me about a time priorities changed suddenly.", answer: "Describe how you confirmed the new goal, re-planned openly, communicated what would move, and kept the team focused. Avoid presenting adaptability as chaos." },
    { id: "behavioral-extra-13", question: "Tell me about a time you disagreed with your manager.", answer: "State the business goal, explain your evidence and alternative, listen to the manager's context, and support the final decision professionally. Mention the outcome or lesson." },
    { id: "behavioral-extra-14", question: "Tell me about a time you persuaded stakeholders.", answer: "Connect the proposal to their goals, present evidence and tradeoffs, invite objections, and show the decision or behavior that changed. Avoid saying you simply convinced them." },
    { id: "behavioral-extra-15", question: "Tell me about a time you improved a process.", answer: "Describe the old friction, how you found its cause, the small change you introduced, and the measured improvement. Include how you gained adoption." },
    { id: "behavioral-extra-16", question: "Tell me about a time you handled a production incident.", answer: "Use STAR to cover impact, your role, stabilization, communication, and prevention work. Emphasize calm coordination and learning rather than blame." },
    { id: "behavioral-extra-17", question: "Tell me about a time you delivered bad news.", answer: "Explain how you verified the facts, told the right people early, gave options and impact, and kept updates honest. Do not hide behind vague wording." },
    { id: "behavioral-extra-18", question: "Tell me about a time you had to say no.", answer: "State the request, the constraint or risk, the alternative you offered, and how you preserved the relationship. A good no is specific and connected to priorities." },
    { id: "behavioral-extra-19", question: "Tell me about a time you made a mistake in a team setting.", answer: "Own the mistake, explain how you corrected the impact, tell the team promptly, and identify the guardrail or habit you added afterward." },
    { id: "behavioral-extra-20", question: "Tell me about a time you worked under ambiguity.", answer: "Describe how you turned an unclear goal into assumptions, questions, a small deliverable, and feedback loops. Explain what evidence clarified the path." },
    { id: "behavioral-extra-21", question: "Tell me about a time you had to learn something quickly.", answer: "Explain the outcome you needed, how you selected reliable resources or mentors, how you practiced, and how you applied the learning successfully." },
    { id: "behavioral-extra-22", question: "Tell me about a time you dealt with a difficult customer.", answer: "Describe how you listened, acknowledged impact, separated facts from emotion, set realistic expectations, and followed through. Protect privacy and avoid insulting the customer." },
    { id: "behavioral-extra-23", question: "Tell me about a time you supported a teammate who was struggling.", answer: "Show empathy, ask what support was wanted, agree on a practical next step, and involve the right manager or resource when necessary. Respect boundaries." },
    { id: "behavioral-extra-24", question: "Tell me about a time you improved inclusion on a team.", answer: "Describe the exclusion signal, the change you made to meetings or decisions, and evidence that more people could contribute. Focus on behavior and access, not slogans." },
    { id: "behavioral-extra-25", question: "Tell me about a time you had to balance speed and quality.", answer: "Explain which quality risks were non-negotiable, what scope you reduced, and how you tracked accepted debt. State the outcome and follow-up." },
    { id: "behavioral-extra-26", question: "Tell me about a time you gave someone constructive feedback.", answer: "Use specific behavior and impact, ask for their perspective, agree on a change, and follow up. Describe the conversation respectfully and without exposing private details." },
    { id: "behavioral-extra-27", question: "Tell me about a time you changed your mind.", answer: "State your initial view, the new evidence, how you acknowledged the change, and the decision that followed. Changing your mind should appear evidence-based, not weak." },
    { id: "behavioral-extra-28", question: "Tell me about a time you managed a disagreement in a meeting.", answer: "Explain how you reframed the shared objective, gave people room to be heard, and moved the group to evidence or a decision owner." },
    { id: "behavioral-extra-29", question: "Tell me about a time you took initiative.", answer: "Describe a meaningful problem you noticed, how you validated that it mattered, the action you took within your authority, and the result." },
    { id: "behavioral-extra-30", question: "Tell me about a time you had to work with limited resources.", answer: "Explain the constraint, how you prioritized the highest-value work, what tradeoff you made, and what result you achieved without pretending the limitation did not matter." },
    { id: "behavioral-extra-31", question: "Tell me about a time you resolved a misunderstanding.", answer: "Describe how you checked assumptions, clarified expectations in a direct conversation, and confirmed the shared interpretation. Mention the improved working relationship." },
    { id: "behavioral-extra-32", question: "Tell me about a time you protected confidential information.", answer: "Explain the sensitivity, the access and communication controls you followed, and how you handled a legitimate need without oversharing." },
    { id: "behavioral-extra-33", question: "Tell me about a time you had to prioritize fairness over convenience.", answer: "Describe the affected people and rule, the risk of the convenient option, and the fair process you followed. State the result and any cost honestly." },
    { id: "behavioral-extra-34", question: "Tell me about a time you motivated a team.", answer: "Connect the work to a meaningful outcome, remove blockers, give people ownership, and recognize progress. Avoid claiming motivation came from pressure alone." },
    { id: "behavioral-extra-35", question: "Tell me about a time you delegated successfully.", answer: "Describe the outcome, context, authority, and support you gave, then explain how the person delivered and grew. Do not present delegation as abandonment." },
    { id: "behavioral-extra-36", question: "Tell me about a time you had to recover trust.", answer: "Own the event that damaged trust, communicate transparently, make a specific repair commitment, and show consistent follow-through over time." },
    { id: "behavioral-extra-37", question: "Tell me about a time you disagreed with a technical design.", answer: "Present your concern with evidence, propose an alternative, listen to constraints, and support or revisit the decision using agreed signals." },
    { id: "behavioral-extra-38", question: "Tell me about a time you made work more accessible.", answer: "Describe the barrier, consult the people affected, change the artifact or process, and verify that access improved. Avoid treating accessibility as only a compliance task." },
    { id: "behavioral-extra-39", question: "Tell me about a time you chose integrity over personal benefit.", answer: "State the conflict of interest or pressure, the principle and process you followed, and the result. Keep the example factual and confidential." },
    { id: "behavioral-extra-40", question: "How should you choose stories for behavioral interviews?", answer: "Prepare several recent STAR stories that cover collaboration, conflict, failure, leadership, inclusion, prioritization, and ethical judgment. Adapt one story honestly to the exact question rather than memorizing a script." },
  ],
  "hr-interview-guide": [
    { id: "hr-interview-guide-extra-01", question: "How should you answer tell me about yourself?", answer: "Give a concise present-past-future summary: your current strengths, relevant experience, and why this role is the next step. Keep it professional and relevant rather than reciting your whole life." },
    { id: "hr-interview-guide-extra-02", question: "How should you answer why do you want to work here?", answer: "Connect specific company or role facts to your skills, interests, and career direction. Avoid making the answer only about salary, brand, or convenience." },
    { id: "hr-interview-guide-extra-03", question: "How should you answer what are your strengths?", answer: "Choose two or three strengths relevant to the role and prove each with a brief work example. Describe the behavior and result, not just an adjective." },
    { id: "hr-interview-guide-extra-04", question: "How should you answer what is your weakness?", answer: "Name a real, manageable weakness, explain the situation where it appears, and describe the specific system or habit you use to improve it. Do not use a disguised strength." },
    { id: "hr-interview-guide-extra-05", question: "How should you answer what are your salary expectations in the Philippines?", answer: "Research the role and market, give a reasonable range in Philippine pesos, and state that the full package and responsibilities matter. Ask whether the range is budgeted if appropriate." },
    { id: "hr-interview-guide-extra-06", question: "How should you answer when can you start?", answer: "State your actual notice period and any firm commitments, then give the earliest realistic start date. Do not promise to bypass an employment obligation." },
    { id: "hr-interview-guide-extra-07", question: "How should you answer what is your notice period?", answer: "Give the contractual or customary period in your current employment and explain any flexibility honestly. Mention a planned leave or handover only if it affects the date." },
    { id: "hr-interview-guide-extra-08", question: "How should you discuss work setup preferences?", answer: "State whether you can work onsite, hybrid, or remotely, mention practical constraints early, and connect your preference to how you collaborate effectively. Stay open about the role's actual requirement." },
    { id: "hr-interview-guide-extra-09", question: "How should you answer where do you see yourself in five years?", answer: "Describe the capability, scope, and contribution you want to grow toward, while showing interest in the role's realistic path. Avoid promising a title you cannot control." },
    { id: "hr-interview-guide-extra-10", question: "How should you explain an employment gap?", answer: "Give a brief truthful explanation, mention productive activity or circumstances only as relevant, and return to the skills and motivation you bring now. Do not over-defend it." },
    { id: "hr-interview-guide-extra-11", question: "How should you explain why you resigned?", answer: "Frame the decision around a factual career or role reason, stay respectful, and explain what you are seeking next. Never disclose confidential information or attack a former employer." },
    { id: "hr-interview-guide-extra-12", question: "How should you explain being laid off?", answer: "State that it was a business decision if that is accurate, explain the relevant context briefly, and focus on what you delivered and what you want next." },
    { id: "hr-interview-guide-extra-13", question: "How should you discuss a short tenure?", answer: "Explain the factual reason without blaming people, state what you learned, and show why this role is a better-informed choice. Avoid presenting a pattern of impulsive moves." },
    { id: "hr-interview-guide-extra-14", question: "How should you answer why should we hire you?", answer: "Summarize the role's key needs, your matching evidence, and the outcomes you can help deliver. Keep the claim specific and supported by examples." },
    { id: "hr-interview-guide-extra-15", question: "How should you answer what motivates you?", answer: "Name work conditions and outcomes that genuinely drive you, such as solving difficult problems or helping a team deliver, then connect them to the position." },
    { id: "hr-interview-guide-extra-16", question: "How should you answer what demotivates you?", answer: "Describe a work condition constructively, explain how you manage it, and distinguish a preference from an inability to perform. Avoid criticizing a former employer." },
    { id: "hr-interview-guide-extra-17", question: "How should you answer how do you handle stress?", answer: "Give a concrete method such as clarifying priorities, breaking work down, communicating risk early, and protecting recovery. Add a brief example with a result." },
    { id: "hr-interview-guide-extra-18", question: "How should you answer how do you handle criticism?", answer: "Say that you listen for the specific behavior and impact, ask clarifying questions, and act on useful feedback. Give an example of a change you made." },
    { id: "hr-interview-guide-extra-19", question: "How should you answer are you willing to relocate?", answer: "State your actual flexibility, timeline, and any constraints plainly. Do not imply relocation is possible if you have not considered its practical requirements." },
    { id: "hr-interview-guide-extra-20", question: "How should you answer are you willing to work overtime?", answer: "Say you can support occasional genuine business needs with reasonable notice, while valuing sustainable planning and clear expectations. Ask how often overtime typically occurs." },
    { id: "hr-interview-guide-extra-21", question: "How should you discuss benefits and total compensation?", answer: "Ask for the complete package, including base pay, bonuses, allowances, leave, health coverage, and review timing. Compare the whole offer rather than one number." },
    { id: "hr-interview-guide-extra-22", question: "How should you ask about the interview process?", answer: "Ask what stages remain, who you will meet, the expected timeline, and what each stage evaluates. This helps you prepare without sounding entitled to an outcome." },
    { id: "hr-interview-guide-extra-23", question: "What questions should you ask about the role?", answer: "Ask about the first six months' outcomes, current challenges, decision ownership, team interfaces, and how success is measured. Choose questions that show informed curiosity." },
    { id: "hr-interview-guide-extra-24", question: "What questions should you ask about the manager?", answer: "Ask how the manager gives feedback, sets priorities, supports growth, and handles disagreement. Their answers reveal working norms more usefully than asking whether they are nice." },
    { id: "hr-interview-guide-extra-25", question: "What questions should you ask about team culture?", answer: "Ask how decisions are made, how incidents are handled, how dissent is welcomed, and what behavior earns trust. Prefer examples over slogans." },
    { id: "hr-interview-guide-extra-26", question: "How should you answer a question you do not know?", answer: "Say what you know, state the boundary of your knowledge, explain how you would find the answer, and avoid inventing facts. Honest reasoning is stronger than bluffing." },
    { id: "hr-interview-guide-extra-27", question: "How should you handle an interview question that is unclear?", answer: "Ask a concise clarifying question and restate your understanding before answering. This demonstrates careful communication rather than hesitation." },
    { id: "hr-interview-guide-extra-28", question: "How should you keep an interview answer concise?", answer: "Lead with the answer, give one relevant example or reason, and stop when the question is answered. Ask whether the interviewer wants more detail." },
    { id: "hr-interview-guide-extra-29", question: "How should you use STAR in an HR interview?", answer: "State the Situation and Task briefly, spend most of the answer on your Actions, and finish with a measurable Result or lesson. Keep the story truthful and specific." },
    { id: "hr-interview-guide-extra-30", question: "How should you discuss confidential work in an interview?", answer: "Describe the problem, your responsibilities, and the outcome at a safe level without naming private data, clients, code, or unreleased plans. Offer a sanitized example instead." },
    { id: "hr-interview-guide-extra-31", question: "How should you answer why are you leaving your current job?", answer: "Explain the positive next step you seek, such as scope, learning, or alignment, while remaining factual about the current role. Keep the tone respectful." },
    { id: "hr-interview-guide-extra-32", question: "How should you answer do you have other offers?", answer: "Answer truthfully and share your decision timeline if useful, without using another offer as a threat. You can say you are evaluating opportunities carefully." },
    { id: "hr-interview-guide-extra-33", question: "How should you discuss references?", answer: "Offer people who can speak directly about your recent work, ask their permission first, and provide context about the role. Never list someone without consent." },
    { id: "hr-interview-guide-extra-34", question: "How should you explain a career change?", answer: "Connect the change to a considered interest, transferable evidence, and a realistic learning plan. Show that you understand the new field's day-to-day work." },
    { id: "hr-interview-guide-extra-35", question: "How should you address a qualification you do not have?", answer: "Acknowledge the gap, identify adjacent experience, and explain how you would close it. Do not claim equivalent expertise without evidence." },
    { id: "hr-interview-guide-extra-36", question: "How should you answer what is your preferred management style?", answer: "Describe the clarity, autonomy, feedback, and support you work best with, while showing that you adapt to reasonable management differences." },
    { id: "hr-interview-guide-extra-37", question: "How should you answer what are your career goals?", answer: "Name skills and impact you want to build, connect them to the role, and show flexibility as opportunities and business needs change." },
    { id: "hr-interview-guide-extra-38", question: "How should you close an HR interview?", answer: "Briefly restate your interest and strongest fit, ask about next steps, and thank the interviewer for specific context they shared. Keep the close confident and concise." },
    { id: "hr-interview-guide-extra-39", question: "How should you prepare for an HR interview?", answer: "Review the role, company, your resume, salary range, notice period, and several truthful examples. Practice aloud while keeping answers natural rather than memorized." },
    { id: "hr-interview-guide-extra-40", question: "How should you answer practical HR questions honestly and strategically?", answer: "Prepare clear facts about pay, availability, work setup, location, gaps, and references, then connect them to the role without hiding constraints. Clarity early prevents mismatched expectations later." },
  ],
};